SET default_transaction_read_only = on;
-- #720: every mi_live_trades row FILLED on/after the first window start (closed AND open, so "still open -> next review" is visible).
\copy (SELECT id, ticker, alert_date, account_mode, signal_type, status, entry_attempt, exit_rule, regime, ep_score, catalyst_quality, gap_pct, orb_high, orb_low, atr_14, entry_price, entry_shares, stop_price, hard_stop, risk_dollars, risk_dollars_actual, total_pnl, remaining_shares, hold_days, partial_taken, breakeven_active, exits::text AS exits, pnl_attribution, skip_reason, depth_sell_pending_on, breakout_day0_pp::text AS breakout_day0_pp, created_at, filled_at, closed_at FROM mi_live_trades WHERE filled_at IS NOT NULL AND (filled_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-08-16' ORDER BY filled_at, id) TO STDOUT WITH CSV HEADER
